#pragma once
static const char CAM_MAINTENANCE_PAGE[]=R"HTML(<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gladiator camera maintenance</title><style>:root{color-scheme:dark;font:17px system-ui}body{max-width:650px;margin:30px auto;padding:16px;background:#0c131a;color:#eef5fa}section{padding:20px;background:#17232d;margin:16px 0;border-radius:12px}label{display:block;margin:12px 0}input,button{font:inherit;padding:10px;max-width:100%}input{display:block;width:95%}button{cursor:pointer}output{display:block;white-space:pre-wrap;margin-top:16px}a{color:#82d6ec}</style><h1>Camera maintenance</h1><p><a href="/">Camera</a> · <a href="/api/status">Status</a></p><section><p id="status">Loading camera status…</p><label>CAM maintenance key<input id="key" type="password" maxlength="32" autocomplete="off"></label><label>Camera firmware (.bin)<input id="image" type="file" accept=".bin"></label><p>Keep power connected. Video pauses during the update. The new firmware must reconnect and confirm startup; otherwise the camera returns to the previous firmware.</p><button id="upload">Upload firmware</button><output id="reply" aria-live="polite"></output></section><section><details><summary>Change Wi-Fi settings</summary><label>Wi-Fi name<input id="ssid" maxlength="32"></label><label>Wi-Fi password<input id="password" type="password" maxlength="63" autocomplete="off"></label><label>Gladiator gateway address<input id="gateway" value="http://192.168.8.1" maxlength="63"></label><p>If the camera cannot join its configured network for 30 seconds, it starts a recovery Wi-Fi network. Its Wi-Fi password is the CAM maintenance key. Connect to it and open http://192.168.9.1.</p><button id="save">Save Wi-Fi settings</button></details></section><script>
const $=id=>document.getElementById(id);let before=null;
async function status(){const r=await fetch('/api/status',{cache:'no-store',signal:AbortSignal.timeout(2000)});if(!r.ok)throw Error('Camera status unavailable');const s=await r.json();$('status').textContent=s.firmware+' · '+s.otaSlot+(s.otaPendingVerification?' · startup confirmation needed':'')+' · Recovery Wi-Fi: '+s.recoverySsid;return s;}
async function confirm(){const r=await fetch('/api/confirm',{method:'POST',headers:{'X-Gladiator-Key':$('key').value.trim()},signal:AbortSignal.timeout(2000)});if(!r.ok)throw Error(await r.text());return r.json();}
async function reconnect(){const until=Date.now()+110000;while(Date.now()<until){await new Promise(r=>setTimeout(r,2000));try{const s=await status();if(s.bootId===before.bootId||s.uptimeMs<5000)continue;if(s.otaSlot===before.otaSlot){$('reply').textContent='Update was not retained. The previous firmware is running.';$('upload').disabled=false;return;}if(s.otaPendingVerification)await confirm();const verified=await status();if(verified.otaPendingVerification)continue;$('reply').textContent='Update complete. '+verified.firmware+' confirmed and ready.';$('upload').disabled=false;return;}catch(e){}}$('reply').textContent='Startup was not confirmed. Check the camera status; it should return to the previous firmware. Recovery Wi-Fi can restore network settings.';$('upload').disabled=false;}
$('upload').onclick=async()=>{try{const file=$('image').files[0],key=$('key').value.trim();if(!file)throw Error('Select a CAM firmware.bin.');if(!/^[a-fA-F0-9]{32}$/.test(key))throw Error('Enter the 32-character CAM maintenance key.');before=await status();if(!before.otaEnabled)throw Error('OTA is unavailable.');if(before.otaPendingVerification){await confirm();before=await status();}if(file.size<512||file.size>before.otaMaxBytes)throw Error('Firmware file is too small or exceeds the update slot.');$('upload').disabled=true;const xhr=new XMLHttpRequest();xhr.open('POST','/api/ota');xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.setRequestHeader('X-Gladiator-Key',key);xhr.timeout=130000;xhr.upload.onprogress=e=>{if(e.lengthComputable)$('reply').textContent='Uploading '+Math.round(e.loaded/e.total*100)+'%';};xhr.onload=()=>{if(xhr.status!==200){$('reply').textContent=xhr.responseText||'Update rejected.';$('upload').disabled=false;return;}$('reply').textContent='Uploaded. Waiting for the camera to reconnect and confirm startup…';reconnect();};xhr.onerror=xhr.ontimeout=()=>{$('reply').textContent='Upload interrupted. Check camera status before retrying.';$('upload').disabled=false;};xhr.send(file);}catch(e){$('reply').textContent=e.message;$('upload').disabled=false;}};
$('save').onclick=async()=>{try{const r=await fetch('/api/config',{method:'POST',headers:{'Content-Type':'application/json','X-Gladiator-Key':$('key').value.trim()},body:JSON.stringify({ssid:$('ssid').value,password:$('password').value,gatewayUrl:$('gateway').value}),signal:AbortSignal.timeout(5000)});if(!r.ok)throw Error(await r.text());$('reply').textContent='Settings saved. Camera reconnecting. Use recovery Wi-Fi if the new connection fails.';}catch(e){$('reply').textContent=e.message;}};
status().catch(e=>$('status').textContent=e.message);
</script></html>)HTML";
